import openpyxl, re
from openpyxl.utils import get_column_letter

wb = openpyxl.load_workbook('/mnt/spreadsheet_data/spreadsheet/10_Debugging/input_files/Inconsistent Color Coding_input.xlsx')

def color_key(font):
    c = font.color
    if c is None: return 'none'
    if c.type == 'rgb': return 'rgb:'+str(c.rgb)
    if c.type == 'theme': return 'theme:%s tint:%s'%(c.theme, c.tint)
    if c.type == 'indexed': return 'indexed:%s'%c.indexed
    return str(c)

def classify(cell):
    v = cell.value
    if v is None: return None
    if isinstance(v, str) and v.startswith('='):
        # formula
        body = v[1:]
        # pure reference: only cell refs, ranges, sheet refs, colons, commas, $, +? 
        # pure ref = single ref or range, possibly with sheet name, no operators/functions
        s = body.strip()
        # remove sheet quotes
        if re.fullmatch(r"(?:'[^']+'|[A-Za-z0-9_]+!)?\$?[A-Z]{1,3}\$?[0-9]+(?::\$?[A-Z]{1,3}\$?[0-9]+)?", s):
            return 'ref'
        return 'formula'
    else:
        return 'hard'

from collections import Counter
cnt = Counter()
mismatches = []
for ws in wb.worksheets:
    for row in ws.iter_rows():
        for cell in row:
            if cell.value is None: continue
            cl = classify(cell)
            ck = color_key(cell.font)
            cnt[(cl, ck)] += 1
            mismatches.append((ws.title, cell.coordinate, cl, ck, repr(cell.value)[:60]))

for k,v in sorted(cnt.items(), key=lambda x:-x[1]):
    print(k, v)

